import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../../../features/auth/context/AuthContext';
import { deleteBook } from '../services/booksApi';
import { useToast } from '../../../components/common/Toast';
import ConfirmDialog from '../../../components/common/ConfirmDialog';
import Button from '../../../components/common/Button';

export default function BookCard({ book, onDeleted }) {
  const { user } = useAuth();
  const toast = useToast();
  const canManage = user?.role === 'admin' || user?.role === 'librarian';
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [deleting, setDeleting] = useState(false);

  const handleDeleteClick = () => {
    setConfirmOpen(true);
  };

  const handleDeleteConfirm = async () => {
    setDeleting(true);
    try {
      await deleteBook(book.id);
      setConfirmOpen(false);
      toast('Book deleted successfully', { variant: 'success' });
      if (onDeleted) onDeleted();
    } catch (err) {
      setConfirmOpen(false);
      if (err.response?.status === 404) {
        if (onDeleted) onDeleted();
        toast('This book no longer exists. Refreshing list.', { variant: 'warning' });
      } else {
        toast(err.response?.data?.detail || err.response?.data?.title || 'Delete failed. Please try again.', { variant: 'error' });
      }
    } finally {
      setDeleting(false);
    }
  };

  return (
    <div className="book-card">
      <img src={book.cover || '/assets/images/default-cover.svg'} alt={book.title} />
      <div className="book-card-body">
        <h4>{book.title}</h4>
        <p>{book.authors?.map((a) => a.name).join(', ')}</p>
        <span className={`status status-${book.available_copies > 0 ? 'available' : 'unavailable'}`}>
          {book.available_copies > 0 ? `${book.available_copies} available` : 'Unavailable'}
        </span>
        <div className="book-card-actions">
          <Link to={`/books/${book.id}`}>View Details</Link>
          {canManage && <Link to={`/books/${book.id}/edit`}>Edit</Link>}
          {canManage && <Button type="button" variant="ghost" size="sm" onClick={handleDeleteClick}>Delete</Button>}
        </div>
      </div>
      <ConfirmDialog
        isOpen={confirmOpen}
        onClose={() => setConfirmOpen(false)}
        onConfirm={handleDeleteConfirm}
        title="Delete Book"
        message={`Are you sure you want to delete "${book.title}"? This action cannot be undone.`}
        confirmText="Delete"
        danger
        loading={deleting}
      />
    </div>
  );
}
